export const COMPENDIUM_REALITE_V9_CRAWLERS_PNJ_PDF_0 = [{"id":"pnj-crawlers-antisysteme-p6-ryan-rowe","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ryan Rowe","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Raising Freedom","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Ryan Rowe","identity_keys":["Ryan Rowe","The Raiser : Ryan Rowe"],"statut":"Chef des insurgés","organisation":"Raising Freedom","age":"41 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p6-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ryan Rowe"],["Alias / désignation","The Raiser : Ryan Rowe"],["Âge apparent","41 ans"],["Affiliations","Crawlers : Insurgés"],["Nationalité d’origine","Américaine"],["Organisation","Raising Freedom"],["Statut","Chef des insurgés"],["Nature","humaine"]]}]},{"id":"antisysteme-p6-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ryan Rowe était un policier sans trop de motivation, membre du SWAT, il vivait une vie assez simple, sans prétention. Son ex-femme le quitta quand en 2023, après les massacres des soldats américains, il refusa de s’engager dans l’armée, le traitant de lâche. Pour lui, tout risquait de foutre le camp si on délaissait la police et il ne se trompa pas. La corruption explosa et dès qu’un policier n’était pas un vendu, la mairie le faisait être engagé de force pour l’armée ou le faisait abattre. Il ne fit profil bas que quelques années, préférant ne pas se mêler des affaires de Bentley et O’Dalaigh qui voulaient changer la police. Lui, sa vie changea lors de « la marche des enfants », où des milliers de gens mirent leurs gosses et les étudiants devant la cohorte de manifestants, et où le maire ordonna de les massacrer. Il brula des fourgons et guida lesmanifestants pour qu’ils ne fuient. Il se fit tirer dessus par ses anciens collègues et en tua, mais sa rage de ce jour-ci ne le quitta jamais. Celui qui n’était qu’un cynique bourrin devint le plus grand guerrier de l’insurrection civile, sacrifiant son corps pour avoir des armesà la hauteur de ses ennemis, Raiser faisant régulièrement face à des chars ou équivalents désormais."}]},{"id":"antisysteme-p6-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p6-max-sharp","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Max Sharp","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Raising Freedom","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Max Sharp","identity_keys":["Max Sharp","The max murder : Max Sharp"],"statut":"Insurgés","organisation":"Raising Freedom","age":"31 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p6-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Max Sharp"],["Alias / désignation","The max murder : Max Sharp"],["Âge apparent","31 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","Américaine"],["Organisation","Raising Freedom"]]}]},{"id":"antisysteme-p6-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Max Sharp est le bras droit de « Raiser », l’un des trois grands noms de l’insurrection américano￾californienne. Max est probablement encore plus violent et extrême que Raiser, au point d’être surnommé « Max Murder » un nom obtenu en 2031 quand il lança un raid sur une usine-village de yellowfood corp, près de Phoenix, ne laissant aucun corporatiste en réchapper."}]},{"id":"antisysteme-p6-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","duc Focalor -Maximilien de Robespierre"],["Nature réelle","Daemon"],["Âge réel / complément","???"],["Statut","figure des Insurgés"]]},{"type":"p","text":"Focalor n’est pas un nom de démon très connu et pourtant c’est un duc actuel de Baal, créé récemment puisqu’il n’a que quelques siècles. Autrefois, on le connaissait comme l’humain Maximilien de Robespierre et il reste une grande figure de l’Histoire Française peu importe qu’on le retienne en bien comme en mal, au point que Baal, même déchu ne s’acharna à en faire un subordonné. Il incarne la dignité humaine, l’insoumission de fait, tous les mortels se valent pour lui et aucun d’entre eux n’a à se soumettre à un autre humain. Hélas, il a tendance à être assez indépendant, et s’est déjà confronté à d’autres Daemons et Angelus."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p7-lyn-gordon","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Lyn Gordon","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Raising Freedom","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Lyn Gordon","identity_keys":["Lyn Gordon","The Roar: Lyn Gordon"],"statut":"figure des Insurgés","organisation":"Raising Freedom","age":"24 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p7-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Lyn Gordon"],["Alias / désignation","The Roar: Lyn Gordon"],["Âge apparent","24 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","Américaine"],["Organisation","Raising Freedom"],["Statut","figure des Insurgés"],["Nature","humaine"]]}]},{"id":"antisysteme-p7-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Lyn est une grande figure de « Raising Freedom », elle est peut-être jeune mais elle est animée d’une gigantesque colère qu’elle partage avec les autres membres. Trop jeune pour la guerre, elle a été témoins des changements sociétaux sans rien pouvoir y faire, elle est comme énormément de jeunes de sa tranche d’âge, aussi paumée que furieuse contre les plus anciens. Ils ont pourri le climat, ils ont pourri la société, l’économie, les ressources, ils ont même pourri les règles du jeu. Malgré sa rage, elle reste jeune et influençable, elle est une excellente boxeuse parce qu’elle est fan de Leslie Wright, elle s’est fait augmenter la poitrine pour être comme Siobhain, elle a de nombreuses augmentations d’ailleurs, pas qu’esthétiques pour compenser son manque d’expérience au combat. Elle est officiellement la petite amie de Raiser, mais c’est plus une de ses volontés à elle de se présenter officiellement comme telle, pour asseoir un peu de légitimité en étant la partenaire de son mentor. Elle n’a pas d’études ou de formation, elle est même illettrée alors elle s’énerve vite quand on se moque de son niveau culturel."}]},{"id":"antisysteme-p7-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"p","text":"En vérité, elle est plus une mascotte chez les insurgés, on ne la laisse jamais vraiment commander."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p7-merlynn-bryant","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Merlynn Bryant","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Raising Freedom","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Merlynn Bryant","identity_keys":["Merlynn Bryant","Pyromom : Merlynn Bryant"],"statut":"figure des Insurgés","organisation":"Raising Freedom","age":"49 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p7-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Merlynn Bryant"],["Alias / désignation","Pyromom : Merlynn Bryant"],["Âge apparent","49 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","américaine"],["Organisation","Raising Freedom"],["Statut","figure des Insurgés"],["Nature","humaine"]]}]},{"id":"antisysteme-p7-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Melynn est une insurgée des Rasing Freedom, elle a perdu ses deux filles et son fils à la guerre. Elle était pompière et a perdu son boulot quand elle a refusé de venir servir de renfort à la sécurité d’un conseiller municipal alors qu’un incendie se propageait. Avant 2030, ; de nombreux incendies avaient lieux à cause des étudiants et des manifestants, elle était toujours volontaire pour les éteindre quand elle craqua, elle préféra rejoindre l’insurrection et expliquer aux jeunes comment et quoi incendier plutôt que de les en empêcher, elle essaya de donner des conseils pour éviter que les victimes collatérales ne soient trop nombreuses, elle devint la « Pyromom »."}]},{"id":"antisysteme-p7-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"p","text":"Elle est activement recherchée et les cultes néopaïens du feu la voient comme une élue, elle prie les dieux du feu par désespoir plus que par foi, mais elle n’a pas de pouvoir autre que ses connaissances de pompier. C’est une combattante peu augmentée mais terriblement pugnace."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p9-kristina-ruiz","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"kristina Ruiz","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Health Age","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"kristina Ruiz","identity_keys":["kristina Ruiz","The Plague Queen : kristina Ruiz"],"statut":"Chef des insurgés","organisation":"Health Age","age":"31 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p9-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","kristina Ruiz"],["Alias / désignation","The Plague Queen : kristina Ruiz"],["Âge apparent","31 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","américaine"],["Organisation","Health Age"],["Statut","Chef des insurgés"],["Nature","humaine"]]}]},{"id":"antisysteme-p9-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Kristina Ruiz est généreuse, dévouée, aimante, elle a l’aura des plus grandes figures se dévouant aux faibles, malades et pauvres. Ses laboratoires et cliniques illégales fleurissent comme des champignons, la clinique d’Elizabeth M. Karnstein, une ancienne subordonnée, elle aussi virée de sunways, n’est qu’une de ces créations. Les underlives et crawlers la respectent et quand ils voient les « corbeaux d’Asclépios », les troupes de « Health Age », ils sont le plus souvent assez rassurés, puisque presque tous les membres de ces insurgés ont une formation de secouristes voire sont d’anciens médecins militaires ou urgentistes."}]},{"id":"antisysteme-p9-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","??? ns"]]},{"type":"p","text":"La triste vérité est qu’il vaudrait mieux les fuir s’ils ont leur masque de docteur de la peste et leurs bouteilles d’oxygènes, c’est qu’ils empoisonnent ou contaminent l’air et souvent depuis un moment quand on les repère. C’est parce que Kristina est aussi sadique et détraquée qu’elle est redoutée même par l’Iron Pain et le Raiser, elle ne se refuse aucune extremité pour abattre les corporations et n’a vraiment rien à faire des gens en vérité, derrière son image de quasi sainte, on l’a déjà vu filer un assortiment hormonal à une femme pleurant ses enfants, la rendant obsédée sexuelle pour compenser."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p9-chon-hyun-sook","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Chon Hyun-Sook","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Health Age","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Chon Hyun-Sook","identity_keys":["Chon Hyun-Sook","The Innocent Pandemic : Chon Hyun-Sook"],"statut":"figure des insurgés","organisation":"Health Age","age":"48 ans","nationalite":"coréenne"},"sections":[{"id":"antisysteme-p9-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Chon Hyun-Sook"],["Alias / désignation","The Innocent Pandemic : Chon Hyun-Sook"],["Âge apparent","48 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","coréenne"],["Organisation","Health Age"],["Statut","figure des insurgés"],["Nature","humaine"]]}]},{"id":"antisysteme-p9-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Hyun-Sook est une jeune et jolie insurgée, elle ne sait pas vraiment ce qu’elle fait, elle a été embrigadée parce qu’on oppressait les coréens après la guerre en Californie, elle est souvent prompte à promettre de tout arrêter et son joli visage innocent laisse souvent ses ennemis croire à ce mensonge. Elle n’a rien d’une jeune femme, c’est un colonel nord-coréen qui n’a pas suivi cette faction mais continue la lutte, elle menace régulièrement Kristina, autrefois l’ayant fait travailler pour la grande Corée unifiée, elle a une relation étrange avec Kristina, d’un côté, elle la fait chanter, la menace et l’occasion lui met un coup de genou dans les ovaires pour lui rappeler le respect, mais elle est aussi très dépendante et attachée à l’hispanique, jouant sa petite disciple même aux yeux des autres membres de Health Age, Kristina la déteste le plus souvent, haïssant être menacée ou humiliée, mais elle ne la trahit pas, ne la dénonce pas et ne cherche pas à changer leur relation, une forme d’habitude et d’affection malsaine les liant. Si elle n’a pas rejoint les insurgés norcos, c’est parce qu’elle sait qu’ils n’étaient pas humains."}]},{"id":"antisysteme-p9-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p10-karstryn-ogelgrutten","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Karstryn Ogelgrutten","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Health Age","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Karstryn Ogelgrutten","identity_keys":["Karstryn Ogelgrutten","The blood Painter : Karstryn Ogelgrutten"],"statut":"Insurgés","organisation":"Health Age","age":"29 ans","nationalite":"Allemande"},"sections":[{"id":"antisysteme-p10-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Karstryn Ogelgrutten"],["Alias / désignation","The blood Painter : Karstryn Ogelgrutten"],["Âge apparent","29 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","Allemande"],["Organisation","Health Age"]]}]},{"id":"antisysteme-p10-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Beaucoup de « porbeaux d’Asclepios » sont considérés avec respect et bienveillance, ils attaquent les corporations en se risquant aux maladies, toxines et autres dangers sanitaires, ils n’ont pas peur devenir soigner dans des foyers infectieux quand le gouvernement s’y prend à deux fois avant d’envoyer son premier expert."}]},{"id":"antisysteme-p10-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","Mage"],["Âge réel / complément","194 ans"],["Statut","figure des insurgés"],["Sort de lignée","« trinitroglycérino-hémoglobine »"]]},{"type":"p","text":"En vérité il n’y a bien qu’un seul corbeau qu’on déteste et dont on est certain qu’il n’est JAMAIS là pour soigner, aider ou même compatir : Karstryn. Cette allemande aux yeux orange et à la blondeur peut sembler saine d’esprit au premier regard mais elle est obsédée par la souffrance et la torture. Elle-même torturée plus jeune, elle n’en a pas réchappé mentalement, trouvant du plaisir clairement sexuel à faire saigner ses ennemis et leur injecter nombres de produits pathogènes ou simples drogues pour mieux s’amuser. Mage de la loge de Berlin, elle en a récemment été éjectée quand on a établi ses liens étroits familiaux entre les Ogelgrutten et les Skotia, la famille vampirique que ces mages servaient officieusement. Venue servir Hecate, elle le fait au sein d’Health Age en collaboration avec Mircalla."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p10-omaar-al-bagheri","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Omaar al-Bagheri","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Health Age","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Omaar al-Bagheri","identity_keys":["Omaar al-Bagheri","The Ignoble Butcher : Omaar al-Bagheri"],"statut":"Insurgés","organisation":"Health Age","age":"57 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p10-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Omaar al-Bagheri"],["Alias / désignation","The Ignoble Butcher : Omaar al-Bagheri"],["Âge apparent","57 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","Américaine"],["Organisation","Health Age"]]}]},{"id":"antisysteme-p10-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"« Ignoble Butcher » est un des combattants de health Age, c’est un des rares médecins de guerre revenus de 22-28, non traumatisé mais qui refusa d’exercer dans un hopital ou une quelconque corporation. Après la guerre, Omaar prit le cuir des Hell Angels, aux cotés d’Arthur Bartram, ancien des « Animals », il était « Baboon », le médecin de l’équipe. C’est pendant une bio attaque de sunways contre un quartier abandonné qu’il quitta les motards pour joindre la résistance et les insurgés de « Health Age », face à la mort d’enfants et d’anciens, il quitta ses frères pour une cause plus vertueuse. Avec l’âge il est de plus en plus au QG mais fait office à la fois de médecin mais surtout de tortionnaire, en effet, sa colère froide le mène à torturer les corporatistes, il n’en attends aucun aveu, ne comptant pas les passer devant la justice, aucune repentance, n’étant pas religieux, il veut juste les instruire face à l’impuissance et la souffrance. Il ne tue jamais mais parfois, il semble que la mort est préférable à ce qui reste de ses prisonniers."}]},{"id":"antisysteme-p10-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Mulakhael"],["Nature réelle","angelus (chérubin)"],["Âge réel / complément","??? ans"],["Statut","Figure des insurgés"],["Vertu angélique","veillesse"]]},{"type":"p","text":"Il est le chérubin de l’âge, Mulakhael, un ange inconnu. Il sert Azrael."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p12-osheena-payne","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Osheena Payne","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Iron Revengers","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Osheena Payne","identity_keys":["Osheena Payne","Iron Pain : Osheena Payne"],"statut":"chef des insurgés","organisation":"Iron Revengers","age":"39 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p12-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Osheena Payne"],["Alias / désignation","Iron Pain : Osheena Payne"],["Âge apparent","39 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","américaine"],["Organisation","Iron Revengers"],["Statut","chef des insurgés"],["Nature","humaine"]]}]},{"id":"antisysteme-p12-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"En 2022, Osheena avait 26 ans, ce n’était pas une jeune recrue de l’US. Marines Corp. Très proche de Gerald Ashorn, ce dernier était décrié pour sa tendance à faire monter plus vite des têtes brulées et des combattants du rang face à des officiers d’école, le général justifiait qu’il ne favorisait pas l’origine sociale mais l’extraordinaire compétence d’individu transcendant leur origine, leur formation et les limites humaines, ce fut le cas avec Hailey Powell et plus tard Siobhain Nic Siridean. Osheena a perdu ses bras, une jambe et a été très souvent blessée, la fin de la guerre aurait pu être un soulagement sans son OTS. Elle tua trois personnes avant qu’on ne la condamne à Corcoran. Mais son incarcération l’aida à se reprendre. Certains la comparent sans peur à Hitler et son manifeste « pain and justice » à « mein Kampf ». Pour beaucoup d’insurgés, elle est la « VRAIE » renégate, car elle a un discours politique, libérateur et mène des actions plus tactiques là où un Raiser est dans la réaction, une Plague queen dans le terrorisme idéologique, Osheena se distingue par des propositions de loi et d’action. Les corporation et l’état californien les reçoit, reçoit un ultimatum et sans mesures prises, reçoivent la juste punition une fois le délai dépassé. Plus militarisés que d’autres factions, les Iron Revengers sont lourdement armés et équipés au combat, ils pillent les forces de sécurité sans discontinuer et ont une haine d’Ushkoll."}]},{"id":"antisysteme-p12-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p12-roland-mitchell","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Roland Mitchell","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Iron Revengers","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Roland Mitchell","identity_keys":["Roland Mitchell","The Blackstard : Roland Mitchell"],"statut":"figure des insurgés","organisation":"Iron Revengers","age":"34 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p12-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Roland Mitchell"],["Alias / désignation","The Blackstard : Roland Mitchell"],["Âge apparent","34 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","Américaine"],["Organisation","Iron Revengers"],["Statut","figure des insurgés"],["Nature","humaine"]]}]},{"id":"antisysteme-p12-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Roland est un ancien de l’US. Army. Soldat de l’infanterie, il n’a pas eu de grandes distinctions pendant la guerre, étant assez tardivement déployé et assez terrifié par les combats. Jeté en prison pour avoir tué l’enseignant de son fils, qu’il suspectait d’avoir touché son gamin, il y adopta l’idéologie d’Osheena Payne quand il apprit que son fils était mort d’une pneumonie, faute de soin dans l’orphelinat où il avait été jeté. La colère d’un père en deuil est infinie, ancien membre d’un bataillon d’infanterie lourde, dès qu’on le libéra, il fit crawler pour financer de l’équipement et joindre les insurgés de San Francisco, dans l’immense cratère laissé par l’affaissement des sols après le Big One. Il n’est pas le plus impliqué dans les décisions, il n’en a rien à foutre de la cause ou plutôt, il a une confiance aveugle en Osheena, plus intelligente et plus sage, lui, n’est là que pour être le « Black bastard », « Blackstard », l’exécuteur personnel d’Osheena, un « chevalier » blindé sans aucune peur de la mort et très désireux de tuer le plus de corporatif et de policiers possibles, tout ce qui touche au gouvernement étant cible de sa haine : les responsables de la mort de son fils. Sa personnalité est toutefois moins rude qu’on ne l’imagine, c’est un passionné de nourriture et sa seconde idole après Osheena est la chef Svetalana."}]},{"id":"antisysteme-p12-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","??? ns"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p13-thaddeus-slabaugh","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Thaddeus Slabaugh","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Iron Revengers","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Thaddeus Slabaugh","identity_keys":["Thaddeus Slabaugh","Peace Rainbow ted : Thaddeus Slabaugh"],"statut":"Insurgés","organisation":"Iron Revengers","age":"38 ans","nationalite":"canadienne"},"sections":[{"id":"antisysteme-p13-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Thaddeus Slabaugh"],["Alias / désignation","Peace Rainbow ted : Thaddeus Slabaugh"],["Âge apparent","38 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","canadienne"],["Organisation","Iron Revengers"]]}]},{"id":"antisysteme-p13-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Thaddeus était le fils d’une communauté Amish très religieuse au Canada, ils vivaient dans la Foi et la simplicité. Un jour, un criminel endurci nommé Daniel Gotz est arrivé blesser et a été soigné par des jeunes femmes du village, tout de suite, Thaddeus n’a pas cru à l’histoire du criminel et a bien vu qu’il regardait les jeunes femmes avec vice et perversion, il ne put l’empêcher, le charisme de Daniel l’amenant à corrompre les âmes et les habitudes des amish, sombrant dans la drogue, l’alcool et surtout la plus grande débauche. Là où on aurait imaginé un chef de communauté aller voir les autorités ou des religieux, Thaddeus adopta complétement ce mode de vie, devenant le gourou de cette communauté devenue secte perverse. En février 2024, hélas, le Canada s’engagea dans le conflit asiatique et Thaddeus fut appelé de force à prendre les armes, il ne retrouva pas sa communauté en revenant au Canada alors il s’installa en Californie. Figure d’une bande d’insurgés ni trop religieux ni trop satanistes, il fut assimilé par les Iron Revengers après le massacre de la moitié de ses partisans."}]},{"id":"antisysteme-p13-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","vampire"],["Statut","figure des insurgés"]]},{"type":"p","text":"Vampire transformé par Daniella, c’est un vampire mimétique, c’est-à-dire que son sang est celui de sa maitresse et ses pouvoirs les mêmes, tant qu’elle l’accepte."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p13-mildred-copeland","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Mildred Copeland","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Iron Revengers","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Mildred Copeland","identity_keys":["Mildred Copeland","Nuke Dread : Mildred Copeland"],"statut":"Insurgés","organisation":"Iron Revengers","age":"31 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p13-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Mildred Copeland"],["Alias / désignation","Nuke Dread : Mildred Copeland"],["Âge apparent","31 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","américaine"],["Organisation","Iron Revengers"],["Nature","humaine"]]}]},{"id":"antisysteme-p13-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"« nuke Dread » est une meditech insurgée, elle n’était que technicienne au PCRC et était souvent moquée et malmenée par des ingénieurs et hauts docteurs en mécanique. Elle a travaillé quelques jours sur la seconde phase du projet Phoenix. Après la guerre, elle a été chargée par Hailey Powell de retrouver son amie, Osheena Payne, afin de lui faire savoir qu’elle était en vie, toutefois, Mildred était assez extrême et pour ça, elle ne demanda pas une entrevue avec la prisonnière mais se fit arrêter. Elle adopta son point de vue sur l’insurrection civile et travailla sur des plans d’évasion avant d’être libérée par les mesures du gouvernement Page. En 2034, un mandat d’arrêt tomba sur sa tête, voulant à la mafia russe presque une tonne de combustible nucléaire, elle devint « Nuke Mildread »."}]},{"id":"antisysteme-p13-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","« Riwallawn »"],["Statut","figure des insurgés"]]},{"type":"p","text":"Mildred est une femme très changeante, mais en vérité c’est parce qu’elle est le « chevalier Rivalen », de la « Table ronde », elle se sent appelée par des spectres quant à la chasse mais s’y refuse, la rumeur étant que Leslie Wright ayant un lien avec ces chasseurs, or, Mildred a une peur rare de Leslie, qu’elle pense avoir cautionné les humiliations subies au PCRC."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p15-nathan-chappelle","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Nathan Chappelle","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","La Grande Révolution","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Nathan Chappelle","identity_keys":["Nathan Chappelle","Le révolutionnaire : Nathan Chappelle"],"statut":"Insurgés","organisation":"La Grande Révolution","age":"54 ans","nationalite":"française"},"sections":[{"id":"antisysteme-p15-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Nathan Chappelle"],["Alias / désignation","Le révolutionnaire : Nathan Chappelle"],["Âge apparent","54 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","française"],["Organisation","La Grande Révolution"]]}]},{"id":"antisysteme-p15-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Nathan est né à Strasbourg, en France. Originellement enseignant-chercheur en physique, il a rejoint l’insurrection civile durant les grandes crises économiques et les conflits de guerres civiles en Europe."}]},{"id":"antisysteme-p15-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Ascanius"],["Nature réelle","garou (pelage gris)"],["Âge réel / complément","???"],["Statut","chef des insurgés"]]},{"type":"p","text":"En 266, le meneur « Romulus » fut tué, « Ascanius » le remplaçant à la tête de la « Meute ». Celui de 2035 est devenu le meneur en 2030, bien que ce fût un scientifique à l’origine, avec les affrontements, c’est devenu un leader et un combattant affûté. Son départ pour les Etats-Unis est lié avec l’extermination de la cellule insurgée qu’il menait, il y est allé pour sauver les Garous que des scientifiques de « Sunways corporation » avaient récupéré pour une expérience conjointe avec une corporation asiatique très récente, « Fulldroids corporation » qui transforma en cyborg les garous ainsi enlevés lors de la purge des insurgés. En tant que meneur des pelages gris, il n’a qu’un idéal : la paix de tous les garous et leur sécurité."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p15-jane-costa","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Jane Costa","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","La Grande Révolution","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Jane Costa","identity_keys":["Jane Costa","Pinky foxy : Jane Costa"],"statut":"Insurgés","organisation":"La Grande Révolution","age":"38 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p15-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Jane Costa"],["Alias / désignation","Pinky foxy : Jane Costa"],["Âge apparent","38 ans"],["Affiliations","Crawlers : meditech - insurgés"],["Nationalité d’origine","Américaine"],["Organisation","La Grande Révolution"]]}]},{"id":"antisysteme-p15-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Jane est une meditech des insurgés de la branche de Nathan Chappelle, elle soigne les terroristes de cette branche après leurs assauts contre des corporations, la police ou bien des bâtiments religieux. Bien qu’elle ne soit pas européenne, elle adhère à l’idéologie insurrectionnelle telle que ces insurgés la voient, et non comme le voient les insurgés américains. En tant que louve, elle est sans aucune pitié avec les ennemis mais aussi ses rivaux dans la faction, en effet, elle veut absolument devenir la partenaire unique d’Ascanius et faire valoir son clan."}]},{"id":"antisysteme-p15-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","Loups-garous"],["Âge réel / complément","????"],["Statut","figure des insurgés"],["Grand meneur","Ascanius"],["Pouvoir du sang","sang naturel"]]},{"type":"p","text":"Elle est proche du magicien Faust, elle sait qu’il est mage et il sait qu’elle est un loup-garou, il l’aide à travailler sur la famine blanche et d’autres afflictions des loups-garous, ayant déjà travaillé avec Maximilian Stroheim sur l’équivalent chez les vampires."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p16-isabelle-pinchon","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Isabelle Pinchon","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","La Grande Révolution","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Isabelle Pinchon","identity_keys":["Isabelle Pinchon","La téméraire : Isabelle Pinchon"],"statut":"Insurgés","organisation":"La Grande Révolution","age":"54 ans","nationalite":"française"},"sections":[{"id":"antisysteme-p16-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Isabelle Pinchon"],["Alias / désignation","La téméraire : Isabelle Pinchon"],["Âge apparent","54 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","française"],["Organisation","La Grande Révolution"],["Nature","Humaine (bretonne, c’est à part)"]]}]},{"id":"antisysteme-p16-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Isabelle Pinchon est née en Bretagne, une région française. Elle a été gendarme plusieurs années avant de joindre la légion étrangère. Elle y resta jusqu’aux début de l’insurrection civile, quand le président français opposa à son peuple ses armées. Après quelques actes répréhensibles correspondant aux ordres, le commandement de la légion se constitua indépendant, refusant de servir un dictateur stupide issu de la classe consanguine politique. Isabelle resta dans la « légion libérée » mais une armée indépendante fut ciblée prioritairement et bombardée. L’insurrection civile récupéra les survivants, faisant vite leur choix. Sur ordres de Léon Smirnov, une grande figure des insurgés en 2032, et anciennement son supérieur, elle quitta la France pour préparer l’arrivée massive des insurgés fuyant la répression. Léon explosa quelques jours après son départ."}]},{"id":"antisysteme-p16-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","« Tristan »"],["Âge réel / complément","???"],["Statut","figure des insurgés"]]},{"type":"p","text":"En Californie, elle se révéla être « Tristan », le chevalier de « la table ronde », une faction de chasseurs dirigés par un spectre et Leslie Wright. Elle ne sait pas vraiment quelle faction a la priorité, son destin de chevalier et son amitié pour Leslie étant très forte, mais le devenir de l’insurrection ne se méprise pas."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p16-adalfredo-guastella","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Adalfredo Guastella","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","La Grande Révolution","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Adalfredo Guastella","identity_keys":["Adalfredo Guastella","Il Pericolo : Adalfredo Guastella"],"statut":"figure des insurgés","organisation":"La Grande Révolution","age":"28 ans","nationalite":"italienne"},"sections":[{"id":"antisysteme-p16-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Adalfredo Guastella"],["Alias / désignation","Il Pericolo : Adalfredo Guastella"],["Âge apparent","28 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","italienne"],["Organisation","La Grande Révolution"],["Statut","figure des insurgés"],["Nature","humaine"]]}]},{"id":"antisysteme-p16-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Adalfredo était un étudiant quand les manifestations commencèrent en Italie, il a connu les famines qui ont eu lieu, surtout dans le sud à cause du réchauffement climatique accentué. Ce n’était qu’un sportif rêvant de médaille avant d’intégrer les insurgés Italiens, ce n’était pas un leader ou même une célébrité, juste un bon gars un peu en colère. A chaque mission, chaque attaque, son groupuscule s’amincissait, et à chaque fois il survivait grace ses prouesses physiques. Finalement, après quelques mois, beaucoup de morts et de désertion, il se retrouva le plus aguerri, le plus ancien et le plus expérimenté d’une poignée d’insurgés italiens que contactèrent la grande Révolution. C’est un farouche catholique mais il détestait les réformes trop novatrices du pape, c’est lui qui tenta d’assassiner le prédécesseur de Paladia. La garde suisse l’arrêta mais le relâcha après quelques semaines. Ce qui caractérise le mieux Adalfredo c’est qu’au fond, il n’a pas la motivation d’un véritable insurgé, il fait ce que son équipe lui dit, il le fait bien, si ce n’est mieux que n’importe qui, il survit, le plus souvent mieux que son équipe et passe au projet suivant. Il porte une cicatrice en forme de croix dans le dos, que lui a gravé avec une hallebarde la sénéchale actuelle de la garde pontificale."}]},{"id":"antisysteme-p16-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","????"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p18-alayna-daewynn","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Alayna Daewynn","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Green Fairy Mother","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Alayna Daewynn","identity_keys":["Alayna Daewynn","The Dryad : Alayna Daewynn"],"statut":"Insurgés","organisation":"Green Fairy Mother","age":"25 ans","nationalite":"irlandaise"},"sections":[{"id":"antisysteme-p18-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Alayna Daewynn"],["Alias / désignation","The Dryad : Alayna Daewynn"],["Âge apparent","25 ans"],["Affiliations","Crawlers : enders"],["Nationalité d’origine","irlandaise"],["Organisation","Green Fairy Mother"]]}]},{"id":"antisysteme-p18-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ancien membre de l’IRA véritable, elle a émigré aux Etats-Unis pour assassiner un traitre à la cause puis a complétement disparu des radars pendant plusieurs années. Elle a totalement changé d’appartenance en joignant la faction GFM afin de défendre l’environnement, cependant, elle est à la tête de la branche survivaliste (endrunners) qui s’oppose souvent à la branche activiste (insurgés) de cette même faction. L’opposition est moins idéologique que pratique, c’est sur comment lutter qu’Alayna et Sahamena se déchirent, pas sur le bienfondé de la lutte elle-même."}]},{"id":"antisysteme-p18-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Alayna DAEWYNN"],["Nature réelle","elfes"],["Âge réel / complément","???? ans"],["Statut","figure des insurgés"]]},{"type":"p","text":"Descendante d’elfes sylvains, elle est née sur Terre et fait perdurer l’esprit du Cercle de Chêne. Sa communauté comprend des keltas et autres créatures d’Aèr liées à la nature. Elle est perpétuellement révélée, préférant tuer les curieux au sujet de ses oreilles que de mentir. Disciple de Titania un temps, elle a été recalée de la Chasse Fantastique. Alayna ne manquait pas de compétence pour en être, mais derrière la combattante et l’assassine, il y a une elfe très contemplative ayant un réel besoin de calme et de solitude, pas assez liée à ses frères d’armes de la Chasse, elle ne s’intégrait pas."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p18-sahamena-lannis","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Sahamena Lannis","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Green Fairy Mother","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Sahamena Lannis","identity_keys":["Sahamena Lannis","The Swedish fairy : Sahamena Lannis"],"statut":"Insurgés","organisation":"Green Fairy Mother","age":"39 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p18-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Sahamena Lannis"],["Alias / désignation","The Swedish fairy : Sahamena Lannis"],["Âge apparent","39 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","américaine"],["Organisation","Green Fairy Mother"]]}]},{"id":"antisysteme-p18-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Issue de la grande famille Lanyth (origine elfes sylvains), elle est membre du conseil des Anciens afin de garder une place importante, nombreux sont les elfes ayant jugé leur communauté suffisante pour s’en défaire et ayant été sévèrement punis."}]},{"id":"antisysteme-p18-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Sahamena Lanyth"],["Nature réelle","Elfes"],["Âge réel / complément","???? ans"],["Statut","chef des insurgés"]]},{"type":"p","text":"Malgré une nature assez sauvage, d’elfe forestière, elle n’a aucun souci à vivre dans les forêts urbaines. C’est la plus grande rivale d’Alayna Daewyn. En tant qu’humaine, elle est à la tête d’insurgés environnementalistes, elle lutte contre la non￾réglementation internationale sur les territoires corporatifs. Elle notamment tué plusieurs cadres de yellowfooden « vengeance » de la disparition officielle de 25 espèces sud-américaines dont le Tapir, le jaguar et l’anaconda jaune à la suite de l’implantation de megausines. Elle est aussi intransigeante en tant que crawler qu’elle est diplomate au conseil, elle place au-dessus de tout l’intérêt des elfes néanmoins, bien au-dessus de l’intérêt des autres exilés."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p19-mahkah-jones","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Mahkah Jones","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Green Fairy Mother","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Mahkah Jones","identity_keys":["Mahkah Jones","The Lost Wolf : Mahkah Jones"],"statut":"Insurgés","organisation":"Green Fairy Mother","age":"26 ans","nationalite":"américaine (sioux)"},"sections":[{"id":"antisysteme-p19-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Mahkah Jones"],["Alias / désignation","The Lost Wolf : Mahkah Jones"],["Âge apparent","26 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","américaine (sioux)"],["Organisation","Green Fairy Mother"]]}]},{"id":"antisysteme-p19-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Mahkah est un chaman, il tenta des études dans le commerce, mais ses valeurs morales se conjuguaient peu avec la mentalité attendue d’un commercial. C’est dans l’activisme écologique qu’il trouva sa place. Il n’a jamais été violent ni agressif, c’était un partisan de la modération jusqu’à ce que la tribu sioux de Standing Rock ne soit forcée par Byron industries de céder ses terrains pour exploiter une ressource très profonde. Mahkah n’était pas si malheureux, c’était son moment, celui de négocier et gagner face aux blancs méprisants et leur capitalisme destructeur, il avait un dossier solide, un argumentaire, le juge n’avait aucune raison de refuser… hormis la loi corporative qui, pendant la guerre octroie tout terrain nécessaire à l’effort de guerre aux entreprises les réquisitionnant. Et comme chacun le sait, l’année suivante la loi de propriété étatique corporatiste fut instaurée, pour fermer les yeux sur les droits humains. Il échoua, la tribu fut chassée ou exploitée, on le lyncha pour son échec. Fou de rage, il s’engagea à la GFM pour avoir l’espoir d’avoir un jour, si ce n’est gain de cause, au moins la reconnaissance des méfaits."}]},{"id":"antisysteme-p19-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","garou (pelage noir)"],["Âge réel / complément","???"],["Statut","figure des insurgés"]]},{"type":"p","text":"C’est un meneur de clan loup-garou et un chaman, il parle aux spectres et aux esprits naturels. Il obéit à Talatuwa mais se refuse à vivre dans la grande réserve."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p19-kimmy-oromigna","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kimmy Oromigna","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Green Fairy Mother","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Kimmy Oromigna","identity_keys":["Kimmy Oromigna","The Red Apple : Kimmy Oromigna"],"statut":"Insurgés","organisation":"Green Fairy Mother","age":"25 ans","nationalite":"Ghanéenne"},"sections":[{"id":"antisysteme-p19-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kimmy Oromigna"],["Alias / désignation","The Red Apple : Kimmy Oromigna"],["Âge apparent","25 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","Ghanéenne"],["Organisation","Green Fairy Mother"]]}]},{"id":"antisysteme-p19-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Kimmy est originaire du Ghana. Dès ses 14 ans, son père, un riche homme d’affaires a décidé de l’envoyer vivre aux Etats-Unis, avec un tuteur. Hélas pour lui, la jeune fille n’était pas faite pour les études et les Etats-Unis, surtout la Californie, offrirent bien trop de distraction. Elle se passionna pour les grands espaces et les voyages et devint guide touristique, mais à force de travailler avec les touristes, elle constata le délabrement de la nature, l’irrespect des gens et leur inculture. Elle se rapprocha d’activistes écologistes de plus en plus, parfois elle dénonça de riches clients sans aucune forme de scrupules. Désormais, elle est une des grandes figures de GFM, et une néopaïenne qui incite fortement à prier Gaïa."}]},{"id":"antisysteme-p19-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Erytheia"],["Nature réelle","Nymphe (dryade)"],["Âge réel / complément","????"],["Statut","figure des insurgés"]]},{"type":"p","text":"Nymphe, Erytheia est une Hespéride donc une dryade. Esprit de la nature, elle sert sa mère, Gaïa, la grande nymphe ancienne et essaye de cadrer « Green fairy Mother » avec les volontés des nymphes. Elle n’ignore mais se faisant, elle lutte contre les elfes, en effet, ces derniers, Alayna par exemple ne communiquent pas avec les esprits naturels de la Terre mais ceux importés d’Aèr. Elle a du mal à prendre le contrôle puisqu’elle se désintéresse vite des choses. On la surnomme « la rouge » parce que ses écorces dans sa forme révélée sont d’un rouge sang."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p21-coral-hope","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Coral Hope","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Mermaid Soldiers","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Coral Hope","identity_keys":["Coral Hope","the Tsunamilady : Coral Hope"],"statut":"Insurgés","organisation":"Mermaid Soldiers","age":"26 ans","nationalite":"australienne"},"sections":[{"id":"antisysteme-p21-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Coral Hope"],["Alias / désignation","the Tsunamilady : Coral Hope"],["Âge apparent","26 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","australienne"],["Organisation","Mermaid Soldiers"]]}]},{"id":"antisysteme-p21-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Personne ne peut rester de marbre quand « ironqueen » ou « Raiser » se mettent en marche, résonnant comme des noms porteurs d’un chaos et d’une rare violence, il est un nom qu’on méconnait totalement chez les insurgés californiens et qui, hélas pour la majorité de ceux qui le rencontre, s’avère infiniment plus destructeur : Coral, la « Tsunamilady ». Il suffit d’imaginer une des plus sensuelles bombes anatomiques existantes, toujours en bikini léopard bleu, qui dirige des centaines de plongeurs de combats, des dizaines de navires de guerre d’avant 2022, et des systèmes de bombes sous-marines provoquant des Tsunamis. Elle sévit sur toute la côte ouest des Etats-Unis et est activement recherchée, elle collabore étroitement avec Larry Sundown, son ex."}]},{"id":"antisysteme-p21-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Opis"],["Nature réelle","esprits naturels (nymphes> néréides)"],["Âge réel / complément","plusieurs millénaires."],["Statut","Chef des insurgés"]]},{"type":"p","text":"Officiellement Sérysse, Opis est en vérité une nymphe qui ne s’est pas ennuyée, ayant des oreilles pointues et une peau bleue, elle a pris la première espèce alien qu’on imagina être la sienne quand elle se présenta à l’hydroguard. Sœur d’Amphitrite, elle n’obéit pas à la reine des nymphes marines. Elle déteste les dieux et les cieux, détestant aussi Corolis, la reine des nymphes célestes, ainsi que Gaïa celle des nymphes terrestres et plus ancien esprit élémentaire. Elle n’aime personne, on lui a volé sa dimension, puis ses cités sous-marines, on ne lui volera plus rien, car elle ne possède plus rien."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p21-larry-sundown","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Larry SUNDOWN","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Mermaid Soldiers","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Larry SUNDOWN","identity_keys":["Larry SUNDOWN","The Storm : Larry Sundown"],"statut":"Insurgés","organisation":"Mermaid Soldiers","age":"44 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p21-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Larry SUNDOWN"],["Alias / désignation","The Storm : Larry Sundown"],["Âge apparent","44 ans"],["Affiliations","pègre : mafia navale- crawlers : insurgés"],["Nationalité d’origine","Américaine"],["Organisation","Mermaid Soldiers"]]}]},{"id":"antisysteme-p21-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Larry Sundown est « officiellement » un crawler, un gundriver à la tête du « Speedthunder », un navire surpuissant et rapide permettant d’embarquer une cargaison limitée mais sûre."}]},{"id":"antisysteme-p21-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Laetheas SUNDOSIA"],["Nature réelle","Aseryne (neo-atlante)"],["Âge réel / complément","???"],["Statut","figure des insurgés – chef mafieux"]]},{"type":"p","text":"C’est en vérité le patron de « Red Captain », l’un des types les plus recherchés qui est à la tête d’une flotte de contrebande. Derrière ses tatouages, sa musculature démesurée et son visage terrifiant, Laethas est un duc de très haute lignée atlante. Né sur la nouvelle Atlantide, il admire Lorinae plus qu’aucune autre personne et s’est constitué lui-même sa force de frappe contre les Muliens. En effet, dans sa flotte de contrebande, il a une véritable flotte de guerre, même pas dissimulée une seconde, c’est ce qui fait sa force dans la Réalité mais lui sert aussi dans la Vérité. Il croit que Siobhain est une fille de Kyriak et cherche à l’approcher depuis longtemps. C’est un des rares ducs Atlantes parfaitement bien intégré dans la Réalité, bien plus qu’il ne l’est dans l’Atlantide. Pour cette raison, c’est sa jumelle, Laethia qui assure les tâches administratives pour le duché. Pendant la guerre de 22-28, il était marin sous les ordres de Farah Al’Arshad qu’il respecte encore beaucoup."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p22-asgall-macartain","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Asgall MacArtain","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Mermaid Soldiers","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Asgall MacArtain","identity_keys":["Asgall MacArtain","The Red Captain : Asgall MacArtain"],"statut":"figure des insurgés","organisation":"Mermaid Soldiers","age":"38 ans","nationalite":"Américano-irlandaise"},"sections":[{"id":"antisysteme-p22-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Asgall MacArtain"],["Alias / désignation","The Red Captain : Asgall MacArtain"],["Âge apparent","38 ans"],["Affiliations","crawlers : thugs"],["Nationalité d’origine","Américano-irlandaise"],["Organisation","Mermaid Soldiers"],["Statut","figure des insurgés"],["Nature","humaine (sang de profond)"]]}]},{"id":"antisysteme-p22-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Pêcheur à la base, il ne joignait pas les deux bouts à cause des réformes sur la pêche, du réchauffement climatique et d’autres raisons, jusqu’à ce qu’il commence à voir des riches acheter des navires de guerre abimés ou désuets. S’en emparant de force avec un collectif de pêcheurs, il se sentit l’âme d’un pirate moderne et coula plusieurs navires d’émigrés politiques. MacArtain est un criminel et un voleur, à l’instar des bikers, il profite de la mer pour fuir hors de la juridiction du LAUS et commerce avec les branches portuaires des mafias. Il a une audace rare et il sert sans faillir son « boss », Larry Sundown. Asgall est une ordure mais un capitaine qui sait être adoré de ses équipages, il aime ses hommes et n’est pas le genre à les sacrifier, en revanche, absolument toutes les formes de vies n’étant pas sur son navire ne représentent rien à ses yeux. C’est un malade mental qui n’a aucun affect tant qu’il ne voit pas les gens en face de lui, qu’il ne partage pas leur quotidien, il a tué son propre frère pour avoir 2500 dollars de plus d’héritage, il ne l’avait pas vu depuis 17 ans. Sa mère aurait été violée en Irlande, par un profond alors qu’elle marchait sur la plage, c’est une origine qui émane de lui, malfaisante même si Asgall n’en a pas conscience."}]},{"id":"antisysteme-p22-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","???"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p22-miwatani-raichoko","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Miwatani Raichoko","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Mermaid Soldiers","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Miwatani Raichoko","identity_keys":["Miwatani Raichoko","Otohime : Miwatani Raichoko"],"statut":"figure des insurgés","organisation":"Mermaid Soldiers","age":"29 ans","nationalite":"japonaise"},"sections":[{"id":"antisysteme-p22-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Miwatani Raichoko"],["Alias / désignation","Otohime : Miwatani Raichoko"],["Âge apparent","29 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","japonaise"],["Organisation","Mermaid Soldiers"],["Statut","figure des insurgés"],["Nature","Humaine (semi-esprit)"]]}]},{"id":"antisysteme-p22-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Raichoko était jeune pendant la guerre, elle n’y participa pas vraiment et le regrette assez."}]},{"id":"antisysteme-p22-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","????"]]},{"type":"p","text":"Dernière survivante des Miwatani, elle était destinée à reste miko dans un sanctuaire insulaire, gardant une vieille caisse de bois immergé dans un puit où une légende locale relatait qu’un dragon y avait déposé son cœur pour s’engager auprès d’une humaine. Quand les mermaids attaquèrent et pillèrent son île, elle fut écœurée de voir que le contenu du coffre était un vieux katana boueux, de fait, toute la légende une connerie. Loin de les pourchasser pour la vengeance, elle resta avec les agresseurs, ne croyant plus en rien. Elle devint « Otohime » même si les autres préfèrent l’appeler « la fille du dragon » un surnom un peu cliché à son gout, mais la légende voulant que la déesse Otohime soit la fille de Ryujin, rien d’incohérent avec son choix de surnom. Tsunamilady envoie la « frégate des dragons » quand elle veut voir le sang couler et Raichoko est alors amenée à faire assassine. Elle a le katana boueux toujours, quelque chose l’empêchant de le jeter. Elle est la fille du daemon Zagan, Ao Guang de son identité première, la « nymphe » aquatique, le roi dragon. Elle est plus que jamais proche d’Otohime de fait sans le savoir et gardienne d’un katana Mulien."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p24-kang-sung-hyung","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kang Sung-Hyung","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Seungli","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Kang Sung-Hyung","identity_keys":["Kang Sung-Hyung","The commander Kang : Kang Sung-Hyung"],"statut":"Insurgés","organisation":"Seungli","age":"53 ans","nationalite":"Coréenne"},"sections":[{"id":"antisysteme-p24-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kang Sung-Hyung"],["Alias / désignation","The commander Kang : Kang Sung-Hyung"],["Âge apparent","53 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","Coréenne"],["Organisation","Seungli"]]}]},{"id":"antisysteme-p24-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"-Statut : chef des insurgés Trucidé par Hailey Powell à la fin de l’année 2028, il était le général des armées Nord-Coréennes le plus respecté. Il fut soigné et amené en Californie à l’insu des autorités dès 2030 pour organiser l’insurrection des « ombres de Pyongyang ». Il abreuve les insurgés des autres factions de fausses informations et organise des mises à morts de vétérans américains. On le décrit comme un monstre, mais ses hommes sont d’une loyauté sans égale pour lui. Il est décrit par eux comme juste et vertueux."}]},{"id":"antisysteme-p24-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Saoden II-B2"],["Nature réelle","Talass"],["Âge réel / complément","530 ans"]]},{"type":"p","text":"Saoden est un talass comme aucun autre, rongé par la haine et l’envie de vengeance, il est plus proche d’un humain qu’aucun autre dans sa structure de pensée. Intelligent et tacticien, c’est aussi un combattant de première ligne. Il ne reste qu’assez peu de son corps d’origine qui fait de lui le « Menolass » selon les extrals du GAAC, le considérant plus comme un Menomahs qu’un Talass. Seules Lisa Eredhès et Tejana peuvent le raisonner quand il décide d’un massacre, la première étant une amie à qui il doit plusieurs fois la vie et la seconde, il n’a pas pu empêcher l’attaque sur son monde malgré tous ses efforts, s’en voulant bien qu’elle ne soit Ad’rak elle-même."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p24-soouk-32","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"So’Ouk-32","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Seungli","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"So’Ouk-32","identity_keys":["So’Ouk-32","The green mantis : Yu Soo-Kyung"],"statut":"Insurgés","organisation":"Seungli","age":"48 ans","nationalite":"Coréenne"},"sections":[{"id":"antisysteme-p24-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","So’Ouk-32"],["Alias / désignation","The green mantis : Yu Soo-Kyung"],["Âge apparent","48 ans"],["Affiliations","crawlers : insurgés norco"],["Nationalité d’origine","Coréenne"],["Organisation","Seungli"]]}]},{"id":"antisysteme-p24-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Elle commença en bas de l’échelle, montant les grades pendant la guerre. Soldate d’élite et une des grandes héroïnes de la guerre de 22-28 du côté de la Corée du nord, elle était aussi à l’œuvre dans la capture des scientifiques plus tôt. En 2029, avec son armure de combat, elle attaqua le QG de la Raven qui se construisait, A-man et un groupe de militaires l’arrêtant. En 2034, c’est caltech qu’elle visa, mais Leslie Wright et Scott Riggs l’arrêtèrent, le VP d’Ushkoll enfermant la général norco à Corcoran où elle est encore. Chacune des 31 fois où une So’ouk est née, elle reçut la souffrance de So’ouk-1. Cette itération était vive et désireuse de ne plus être victime. Pilote exceptionnelle et combattante au couteau plus agile qu’aucun autre membre de l’Emeraude, elle a régulièrement été la personne de confiance du général Saoden. Plusieurs fois, elle a croisé la route de Katja et à chaque fois, le regard de la trolle la perturba."}]},{"id":"antisysteme-p24-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Yu Soo-Kyung"],["Nature réelle","Talass"],["Âge réel / complément","???"],["Statut","figure des insurgés"]]},{"type":"p","text":"Enfermée, elle ne s’échappa pas, discutant plusieurs heures avec la patronne d’ushkoll qui semblait comprendre parfaitement la souffrance des Talass de l’Emeraude, chacun naissant avec les sentiments et des souvenirs de celui ayant vécu le massacre par l’armée noire."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p25-wang-gyeong-su","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Wang Gyeong-Su","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Seungli","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Wang Gyeong-Su","identity_keys":["Wang Gyeong-Su","The white monkey : Wang Gyeong-Su"],"statut":"figure des insurgés","organisation":"Seungli","age":"78 ans","nationalite":"nord-coréenne"},"sections":[{"id":"antisysteme-p25-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Wang Gyeong-Su"],["Alias / désignation","The white monkey : Wang Gyeong-Su"],["Âge apparent","78 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","nord-coréenne"],["Organisation","Seungli"],["Statut","figure des insurgés"],["Nature","humaine"]]}]},{"id":"antisysteme-p25-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Le général Wang était un desplus respectés avant que le général Kang e débarque avec son projet d’expansion éclair. Longtemps opposé à ces captures de scientifiques et l’idée d’attaquer tous les pays limitrophes, il a été conspué et mis de côté pendant le début de la guerre, totalement à l’avantage nord￾coréen. L’ironie du sort c’est que le jour de son exécution officieuse, la suprême commandeure l’annula en voyant un revers au Japon à cause du PCRC et de la black Crow. Elle envoya le vieux général mener les opérations punitives, il s’exécuta, se fit éclater les jambes par des tirs et échoua. L’Alliance du Pacifique commença sa lente reprise du terrain mais sa survie resta une erreur tactique, car dès lors, il rassembla tous les Nord-coréens encore au Japon et pris une position de résistance plus que d’agresseur. On lui doit la majorité des réussites miliaires nord-coréennes après la bataille d’Osaka, la plus grande victoire alliée au Japon. Augmenté, en colère, il n’a pas eu de choix que de joindre la Seungli après la guerre, échappant à l’exécution grâce à ses troupes commandos menant son extraction. Contrairement à Kang, il essaye de négocier avec les gouvernements, mais il n’a rien à proposer de concret et restant un insurgé, pour sa propre survie, personne ne lui fait confiance."}]},{"id":"antisysteme-p25-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","???"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p25-lang-yahui","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Lang Yahui","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Seungli","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Lang Yahui","identity_keys":["Lang Yahui","Calamity Lang : Lang Yahui"],"statut":"figure des insurgés","organisation":"Seungli","age":"42 ans","nationalite":"chinoise"},"sections":[{"id":"antisysteme-p25-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Lang Yahui"],["Alias / désignation","Calamity Lang : Lang Yahui"],["Âge apparent","42 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","chinoise"],["Organisation","Seungli"],["Statut","figure des insurgés"],["Nature","Humaine"]]}]},{"id":"antisysteme-p25-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Lang Yahui était une des rares femmes gradées de l’armée chinoise. De base, elle planifiait de stopper Pyongyang par une frappe décisive sur la capitale, sans combattre en Chine, sans protéger la population, estimant les pertes colossales dans tous les cas mais à l’avantage de la Chine. Elle n’a jamais été écoutée, les généraux ont attendu les coréens pour avoir l’avantage du terrain, l’avantage technologique a surpassé le nombre, leur donnant tort. Alors que des officiers comme Shi Wei se battaient, Yahui proposa un armistice pour épargner ces braves, on lui fit mâcher le traité devant le suprême commander, et on lui enfila un collier explosif pour la faire combattre avec les Nord￾coréens et souligner sa trahison, afin de démotiver les troupes chinoises. Considérée comme la pire des traitresses, elle ne put joindre aucun autre camp que la corée du nord dès lors. En 2035 elle est encore dans la Seungli à cause de sa condamnation à mort pour des crimes de guerre auxquels elle n’a pas participé étant prisonnière, bien que personne ne le considère comme tel. Si elle déteste les norcos, elle doit bien avouer qu’elle n’a qu’eux et qu’avec les années, elle s’y est habituée. Elle excelle en tant que pilote de chasse et est relativement bonne au combat rapproché."}]},{"id":"antisysteme-p25-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","????"]]},{"type":"p","text":"Elle était la femme la plus gradée en vérité et lorsque les nordcoréens ont envahi une partie de la patrie, les autres généraux l’ont méprisé."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p27-ashkii-goldrain","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ashkii Goldrain","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Native Old Blood","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Ashkii Goldrain","identity_keys":["Ashkii Goldrain","The Bison : Ashkii Goldrain"],"statut":"Insurgés","organisation":"Native Old Blood","age":"28 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p27-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ashkii Goldrain"],["Alias / désignation","The Bison : Ashkii Goldrain"],["Âge apparent","28 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","Américaine"],["Organisation","Native Old Blood"]]}]},{"id":"antisysteme-p27-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ahskii est un membre de la communauté Navajo, une nation rattachée aux apaches. Il a fait la guerre comme beaucoup de gens, mais surtout la fin étant donné son âge. Après la guerre il fit carrière dans l’UMA ( ultimate martial arts) en tant que gladiateur de la Talacorp à Vegas. En 2031, il changea de vie après un combat où il frôla la mort. Il épousa un ancien adversaire mais ce dernier fut tué par un garde de la Tala. Il commença à nourrir une certaine colère contre l’hégémonie écrasante de la Tala dans la grande réserve, il devint un partisan de Talatuwa et son plus sbire le plus loyal."}]},{"id":"antisysteme-p27-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Quinametli"],["Nature réelle","Dive"],["Âge réel / complément","???"],["Statut","figure des insurgés"]]},{"type":"p","text":"Avec sa carrure digne d’un berserk d’Aèr, ashkii ne laisse pas indifférent sur ses origines pour ceux qui ne sont pas humains, c’est en vérité un Dive, Quinametli, qui donna son nom à ses descendants. C’est un dive de la seconde ère, celle des « rois », comme Angrboda, Théia et autres, ceux ayant suivi l’ère des fondateurs avec Akvan, Ymir, Surtr ou bien Tartare, son père. Il a pour frère Typhon que tua la déesse Abigor et dont le Mageius serait celui de la mage Dagain. Qunametli a vu son peuple être déchiré par Quetzalcoatl, le « vampire », ses amazones le furent également. Il ignore que Talatuwa est garou."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p27-sikya-hawkins","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Sikya HAWKINS","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Native Old Blood","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Sikya HAWKINS","identity_keys":["Sikya HAWKINS","The Talatuwa : Silkya Hawkins"],"statut":"Insurgés","organisation":"Native Old Blood","age":"62 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p27-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Sikya HAWKINS"],["Alias / désignation","The Talatuwa : Silkya Hawkins"],["Âge apparent","62 ans"],["Affiliations","crawlers : insurgés"],["Nationalité d’origine","américaine"],["Organisation","Native Old Blood"]]}]},{"id":"antisysteme-p27-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Pouvoirs du sang : Le sang vengeur – sang funeste Statut : chef des insurgés Bien qu’elle ne fasse pas son âge, Talatuwa est une femme âgée de 62 ans. Elle n’a pas rajeuni son corps mais son sang de grande Meneuse fait durer sa jeunesse plus longtemps. Elle est à la tête de tous les clans des pelages noirs."}]},{"id":"antisysteme-p27-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Talatuwa"],["Nature réelle","Loups-garous"]]},{"type":"p","text":"Elle mène une rébellion constante contre les autorités de la Grande réserve, contre la loge de la grande réserve (les mages) et contre le gouvernement Californien également. Malgré sa lutte, elle a récemment été vaincue par Tokala, la patronne de la Tala corporation, et si Tokala aurait dû la dévorer et devenir Talatuwa, elle préféra la garder, devenant la « reine des garous » en s’imposant sur chaque meneur. Talatuwa est une femme d’un autre âge, avec la mémoire des générations de Grands meneurs la précédent, elle n’a aucun intérêt pour l’ère actuelle, l’holonet ou tout ce qui touche la technologie qu’elle rejette assez, elle n’estime pas en avoir besoin."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p29-masroora-el-ashraf","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Masroora el-Ashraf","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Insurgent Army of Caspian Survivors","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Masroora el-Ashraf","identity_keys":["Masroora el-Ashraf","Friendless Mash : Masroora el-Ashraf"],"statut":"figure des insurgés","organisation":"Insurgent Army of Caspian Survivors","age":"32 ans","nationalite":"iranienne"},"sections":[{"id":"antisysteme-p29-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Masroora el-Ashraf"],["Alias / désignation","Friendless Mash : Masroora el-Ashraf"],["Âge apparent","32 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","iranienne"],["Organisation","Insurgent Army of Caspian Survivors"],["Statut","figure des insurgés"],["Nature","Humaine"]]}]},{"id":"antisysteme-p29-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Masroora est une combattante s’opposant au régime royal des khayat. Elle était l’amie d’enfance de celui qui devint le prince Kashrim. Le père de Masroora était un haut fonctionnaire d’état et donc elle l’appelait « le petit gueux » pour plaisanter. Quand Naseer, le père de Kahsrim devint l’homme le plus riche d’Iran en quelques mois de guerre en Corée, tout changea entre eux et même si Kahsrim n’a jamais renoncé à son coté aventurier, proche du peuple elle sentit qu’il ne renonçait pas à sa part d’un enrichissement aussi rapide que dangereux pour les Iraniens et leurs voisins. Elle fit approchée par les IACS en raison de cette amitié, piégée on l’utilisa pour tenter de prendre en otage Kahsrim, sous-estimant, hélas, les aptitudes physiques du prince. Ce dernier menaça de mort son amie, piégée, la pensant traitresse et toute sa famille en paya le prix, la poussant, ainsi, à joindre les IACS, sans plus de remords. Elle émigra aux Etats-Unis en 2028, considérant le fait qu’entre des musulmans et des coréens, désormais, le racisme des américains allait vers les asiatiques , un âge nouveau pour l’Islam s’y annonçant et énormément de moyen-orientaux s’y rendaient, le climat étant désastreux au Moyen-Orient de plus, l’avenir n’y brillant vraiment pas."}]},{"id":"antisysteme-p29-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","????"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p29-valerian-gruzinsky","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Valerian Gruzinsky","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Insurgent Army of Caspian Survivors","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Valerian Gruzinsky","identity_keys":["Valerian Gruzinsky","Le resistant sans passion : Valerian Gruzinsky"],"statut":"Insurgés","organisation":"Insurgent Army of Caspian Survivors","age":"45 ans","nationalite":"Géorgienne"},"sections":[{"id":"antisysteme-p29-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Valerian Gruzinsky"],["Alias / désignation","Le resistant sans passion : Valerian Gruzinsky"],["Âge apparent","45 ans"],["Affiliations","Crawlers : insurgés (IACS)"],["Nationalité d’origine","Géorgienne"],["Organisation","Insurgent Army of Caspian Survivors"]]}]},{"id":"antisysteme-p29-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Il a souvent été dit que les insurgés étaient des chômeurs mécontents qui, poussés par la peur de l’ère post Holonet. Ont préféré rejeter les corporations avec violence que travailler dur pour reconstruire le monde. C’est vite oublier les réalités du monde, quand russes, irakiens, Azerbaïdjanais, Kazakhs et iraniens se liguèrent contre les troupes de Wellspring, ce n’était pas pour entretenir un mode de vie paresseux mais défendre l’eau, la mer, les ressources primaires, leur survie. Valerian n’était qu’un soldat et parce que tous les gradés furent tués, il monta à la tête de l’ « Insurgent Army of Caspian Survivors : IACS. Capturé par Wellspring, il ne laissa cela arriver que pour détourner l’attention d’une attaque, puis il s’échappa en Californie."}]},{"id":"antisysteme-p29-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Val’Ohr"],["Nature réelle","Baséanne"],["Âge réel / complément","455 ans"],["Statut","chef des insurgés"]]},{"type":"p","text":"Le Général Val’Ohr de la « Fursha’na », « l’armée vivante » n’est pas n’importe qui, Autrefois, il écrasa une armée Orpacyorse et intégra les matriarches à sa troupe, sa femme, Nea’Aeri est une orpacyorse et il est génétiquement altéré pour être « Basé’yors » désormais. Venu sur Terre pour la protéger et préserver les projets du SMRC, il fut surpris qu’en Géorgie on ne vienne l’emmerder et quand on tua ses enfants, il voua Wellspring à l’enfer. Il sait que la manœuvre ne le visait pas mais le GAAC et la mafia Shaediri visent Nea’Aeri, pour éviter qu’une seconde communauté Orpacyorse ne naisse."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p31-leona-ambersmith","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Leona Ambersmith","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Your Debt, Your Life","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Leona Ambersmith","identity_keys":["Leona Ambersmith","YDYL executioner: Leona Ambersmith"],"statut":"figure des insurgés","organisation":"Your Debt, Your Life","age":"32 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p31-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Leona Ambersmith"],["Alias / désignation","YDYL executioner: Leona Ambersmith"],["Âge apparent","32 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","américaine"],["Organisation","Your Debt, Your Life"],["Statut","figure des insurgés"],["Nature","Humaine (galactique)"]]}]},{"id":"antisysteme-p31-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Leona Ambersmith est une fanatique de l’YDYL, ex-soldate, elle était mercs chez les crawlers quand elle a réalisé que l’échec de Devlin Coyles ne venait pas du choix de la cible contrairement à ce que prône Myra Allan, mais des capacités du bourreau, qui n’en avait aucune. Les « bourreaux de l’YDYL » sont un mouvement pour former ceux qui se décident à appliquer les décisions de l’YDYL."}]},{"id":"antisysteme-p31-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","62 ans"]]},{"type":"p","text":"Les insurgés de l’YDYL n’ont pas de revendication hormis « un monde meilleur », « moins de corrompus » et « justice pour tous », pour eux c’est en réduisant le nombre de « pourris » que l’YDYL désignera comme tel que l’avenir pourra commencer à briller, « un monde idyllique s’obtient par des sacrifices », si quelqu’un scande cela, c’est qu’il est de cette faction et Leona le répète comme une prière. Fanatique ? non, cynique, c’est ce qu’est Leona. C’est une mercenaire galactique employée par Corp+, elle joue son rôle de détraquée mentale afin de tuer ceux qui n’arrangent pas les affaires des corporations galactiques pour se faire, elle a un groupe d’assassin qu’elle a elle-même formé"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p31-myra-allan","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Myra Allan","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Your Debt, Your Life","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Myra Allan","identity_keys":["Myra Allan","YDYL voice: Myra Allan"],"statut":"Insurgés","organisation":"Your Debt, Your Life","age":"29ans","nationalite":"Canadienne"},"sections":[{"id":"antisysteme-p31-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Myra Allan"],["Alias / désignation","YDYL voice: Myra Allan"],["Âge apparent","29ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","Canadienne"],["Organisation","Your Debt, Your Life"]]}]},{"id":"antisysteme-p31-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Myra est une fanatique de l’YDYL (l’IA). Elle a vu sur son holophone les dernières minutes de vie de Delvin Coyles et ce fut une révélation, ce type était porté par une volonté transcendantale. Quelque chose qui amena un underlive à attaquer le plus puissant symbole de l’Alliance gouvernement et Corporation. La nécessité, la causalité oula justice, tout ça à la fois et tout cela, une constellation d’IA évolutives l’ont amené à le faire. Mais il y a des gens qu’il ne vaut mieux pas attaquer, A-man notamment, il faut une voix pour énoncer les évidences, poser les questions... cette voix, Myra devait la devenir. Humathalsiosse de naissance c’est une thalsiosse par ses parents mais génétiquement remaniée pourêtre au plus proche d’une humaine, elle n’a aucune capacité physique ni apparences thalsiosse hormis qu’elle peut retenir sa respiration une heure, tout le reste est similaire à une humaine lambda. Elle vieillit plus vite aussi, elle n’a que 19 ans mais en fait la trentaine. L’YDYL est ainsi utilisée pour désigner des gens, de la SA, une branche du REPTILE qui vise à accélérer le réchauffement climatique et l’aridification terrestre. Elle reste une sadique qui aime le pouvoir qu’elle a, rien qu’en donnant un nom."}]},{"id":"antisysteme-p31-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","Thalsios"],["Âge réel / complément","19 ans"],["Statut","chef des insurgés"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p33-yegpor-karamov","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Yegpor Karamov","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Black Star","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Yegpor Karamov","identity_keys":["Yegpor Karamov","Evil Doc: Yegor Karamov"],"statut":"figure des insurgés","organisation":"Black Star","age":"69 ans","nationalite":"russe"},"sections":[{"id":"antisysteme-p33-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Yegpor Karamov"],["Alias / désignation","Evil Doc: Yegor Karamov"],["Âge apparent","69 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","russe"],["Organisation","Black Star"],["Statut","figure des insurgés"],["Nature","Humaine -aberration"]]}]},{"id":"antisysteme-p33-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Yegor karamov était un petit professeur de sciences sans ambitions, son père, Sergey était un prêtre un peu sectaire et son frère, Arkady était un mafieux qui lui paya un voyage pour faire sa demande en mariage à Lydia, sa petite amie."}]},{"id":"antisysteme-p33-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","????"]]},{"type":"p","text":"Le voyage à Barcelone tourna mal, une inconnue tua 42 fois Lydia en ordonnant à Yegor de la ressusciter, le faisant puis la tuant tant qu’il n’y arriva pas, il réveilla les yeux d’or, hérité par son père, un cultiste renégat d’une secte de fléau. Contraint de servir Anadia, il fut renvoyé en Russie où contraint de servir la mafia, ayant la dette de son voyage, il trima pour les deux. Lydia ne fut pas ressuscitée d’ailleurs après cet éveil. Pendant la guerre, il nétait pas renommé alors les coréens ne le capturèrent pas, mais il aida le PCRCen débutant le projet phoenix, cette fois, ressuscitant vraiment des soldats bien qu’il les robotisait pour rendre le processus plus robuste.Il tomba fou amoureux d’une belle décédée nomme Hailey Powell qu’il restaura mieux que les autres. Après la mort de son frère, renégat à l’autorité de Svetlana, il s’échappa et le restaura aussi en le ramenant à la vie. Il a travaillé pour toutes les corporations mécaniques et biologiques mais c’est chez les insurgés qu’il a fini, Alicia Starrogue le forçant à lui construire des soldats en plus de ses Ombres en échange de le laisser étudier le processus de possession."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p33-alicia-starrogue","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Alicia Starrogue","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Black Star","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Alicia Starrogue","identity_keys":["Alicia Starrogue","Fake Silver : Alicia Starrogue"],"statut":"Insurgés","organisation":"Black Star","age":"35 ans","nationalite":"Sud-Africaine"},"sections":[{"id":"antisysteme-p33-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Alicia Starrogue"],["Alias / désignation","Fake Silver : Alicia Starrogue"],["Âge apparent","35 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","Sud-Africaine"],["Organisation","Black Star"]]}]},{"id":"antisysteme-p33-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"« Fake Silver » n’est pas quelqu’un qu’on peut aisément comprendre ni décrire, elle est clairement dotée d’un étrange humour, elle est vive d’esprit et curieuse, elle serait même salope et addicte à la N-sta. Elle ne laisse pas trop de piste pour la différencier de Veronica Silver et en joue énormément pour qu’on la laisse tranquille, salissant la confiance en l’Arbitre parfois."}]},{"id":"antisysteme-p33-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Ira’Xiadror"],["Nature réelle","Homo superior / fléau très ancien"],["Âge réel / complément","???"],["Statut","chef des insurgés"]]},{"type":"p","text":"Ira’Xiadror a suivi Thar’lal rark, le Ganne 0, un éon supérieur fanatique de la technologie, elle est initialement venue se renforcer en communiant avec un « frère », un autre écho des Ténèbres chez les Fléaux, V’aagor, mais aussi pour Lisa Eredhès, Alicia ayant fusionné à Ira’Xiadror, elle a totalement déteint sur le fléau, sa volonté digne d’avoir participé au test Ackeld ayant été suffisante pour survivre à cette fusion."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p35-shaif-almessar","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Shaif Al'Messar","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Alhaqiqa","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Shaif Al'Messar","identity_keys":["Shaif Al'Messar","Weaky Shaif: Shaif Al'Messar"],"statut":"figure des insurgés","organisation":"Alhaqiqa","age":"39 ans","nationalite":"arabe"},"sections":[{"id":"antisysteme-p35-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Shaif Al'Messar"],["Alias / désignation","Weaky Shaif: Shaif Al'Messar"],["Âge apparent","39 ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","arabe"],["Organisation","Alhaqiqa"],["Statut","figure des insurgés"],["Nature","Humaine"]]}]},{"id":"antisysteme-p35-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Shaif Al'Messar est un membre de la secte de l’Alhaqiqa."}]},{"id":"antisysteme-p35-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","????"]]},{"type":"p","text":"C’est le disciple d’Ameena et si elle accompagne le prince chasseur, Hashem El Khayat, lui accompagne une jeune femme elle aussi apprenant les arts secrets de la chasse musulmane. Il n’est pas lui-même chasseur, c’est une forme d’Observateur, même s’il ne fait pas partie de l’Association officiellement. En vérité, il est manipulé par Ameena et il ignore qu’elle est à la fois chasseuse, insurgée mais aussi daemone et qu’elle sert Morrighan, il la pense simplement bénie par les Djinns. s’il n’est pas chasseur, il possède quand même un djinn, « Akhura », un ifrit (nymphe> lampade) assez violent qu’il laisse le posséder à l’occasion quand il doit se défendre. Il croit profondément en la cause de l’Alhaqiqa, sans plans secondaire, en un monde gouverné par la foi et les croyants, sans enjeu politicard et économiques malsain derrière. C’est un mercenaire extrêmement efficace et un tireur d’élite plus encore qu’il n’est bon au corps à corps, expert du combat dans le désert, il apprécie assez l’aridité de la Californie par certains endroits."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p35-ameena-al-gad","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ameena al-Gad","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Insurgés","Alhaqiqa","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Ameena al-Gad","identity_keys":["Ameena al-Gad","Muscle Meena : Ameena al-Gad"],"statut":"Insurgés","organisation":"Alhaqiqa","age":"30 ans","nationalite":"Afghane"},"sections":[{"id":"antisysteme-p35-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ameena al-Gad"],["Alias / désignation","Muscle Meena : Ameena al-Gad"],["Âge apparent","30 ans"],["Affiliations","Chasseurs : observatreurs – crawlers : insurgés chasseurs religieux (musulmans)"],["Nationalité d’origine","Afghane"],["Organisation","Alhaqiqa"]]}]},{"id":"antisysteme-p35-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ameena Al-gad est l’acolyte de Hashem El’Khayat, le prince chasseur."}]},{"id":"antisysteme-p35-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Ghurab"],["Nature réelle","Daemons/keltas"],["Âge réel / complément","????"],["Statut","figure des insurgés"],["Divinité","Morrighan"]]},{"type":"p","text":"En vérité, ce membre de la secte nizarite a pour mission de le tuer s’il perd le contrôle de « Vaanesh », un deimon d’une puissance rare. Corneille de Morrighan et fille de Ibn al-berih (Ishaa), ell est une Observatrice de l’Association également. Même si Hashem n’est pas de l’Association, elle s’occupe de lui régulièrement quand elle n’est pas au « Night Feathers ». Elle fait bien partie des chasseurs musulmans mais sa seule foi va à Morrighan étant une de ses corneilles. Derrière son voile, elle cache une beauté rare et un corps plus qu’athlétique. C’est une assassine et une combattante assez brutale et farouche. Au bar, elle n’aime pas aider les chasseurs ou les daemons trop intellectuels ou séducteurs, elle cherche des gens purs et volontaires, peut-être des gens plus stupides mais ayant du cœur à revendre plus que du cul."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p38-arthur-bartram","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Arthur Bartram","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Hell Angels","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Arthur Bartram","identity_keys":["Arthur Bartram","The Odin’s Bear: Arthur Bartram"],"statut":"Motards","organisation":"Hell Angels","age":"52 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p38-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Arthur Bartram"],["Alias / désignation","The Odin’s Bear: Arthur Bartram"],["Âge apparent","52 ans"],["Affiliations","Crawlers : gundrivers"],["Nationalité d’origine","Américaine"],["Organisation","Hell Angels"]]}]},{"id":"antisysteme-p38-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"N’en déplaise aux insurgés, il existe des forces de combat plus efficace que presque toutes les factions d’insurgés. C’est chez les Hell angels qu’on retrouve un des meilleurs combattant de la Grande Californie : l’ex-colonel Arthur Bartram, héros de 22-28, de l’US. Army. Chef du bataillon spécial des « Animals ». Il a servi Katja de Jankath dans les opérations ultra secrètes du PCRC. C’est un homme violent et impétueux, il en se retrouve pas dans la société de 2035 et c’est pour ça qu’il la rejette en ayant fondé les « cités Bikers », s’emparant par la force de petites ruralités et stations-service pour en faire des fortins évoquant des décors à la madmax. Ce n’est pas un dictateur car il y laisse une grande liberté de choix de vie, cependant, si entrer est assez facile, sortir de ces cités fortifiées ne l’est pas, pas sans un cuir ou une escorte de bikers y ayant été autorisée. C’est un berserk d’Aèr, ils sont très peu nombreux sur Terre et sa femme est une immigrée très récente qu’il a été obligée de faire venir exprès pour fonder une famille. Bien qu’assez honorable, il est profondément misogyne, les « femelles » ont un rôle essentiellement sexuel pour lui à quelques exceptions rares qu’il estime avec loyauté et admiration, comme Katja ou Veronica par exemple."}]},{"id":"antisysteme-p38-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","berserk"],["Statut","Chef de Motorcycle Club"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p38-janyn-yates","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Janyn Yates","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Hell Angels","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Janyn Yates","identity_keys":["Janyn Yates","Chapter “Avenging Angels” : Janyn Yates"],"statut":"présidence de Motorcycle Club","organisation":"Hell Angels","age":"26 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p38-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Janyn Yates"],["Alias / désignation","Chapter “Avenging Angels” : Janyn Yates"],["Âge apparent","26 ans"],["Affiliations","crawlers : gundrivers"],["Nationalité d’origine","Américaine"],["Organisation","Hell Angels"],["Statut","présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p38-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Fille de Malcom Yates, qui avait la présidence du chapitre le plus influent des Angels, elle était impliquée dans le changement de règles pour les clubs, loin d’être une fille à papa, elle soutenait Bartram et quand il brisa la nuque de Malcom dans leur duel pour décider de qui dirigeait, elle n’en fut pas outre mesure choquée. Elle n’a pas fait la guerre, mais elle baigne dans l’ambiance des bars et des clubs de motards depuis sa naissance. C’est une dure à cuir et elle tient son chapitre « Avenging Angel » comme un tyran. Elle a du mal à respecter le statut quo avec les Cruisers et vient régulièrement chercher la merde à Los Angeles, le terrain le plus neutre, sacré même, de toute la Californie. Elle se pense capable de dérouiller la Silver, qui est globalement LA raison du statut quo entre mafias et entre clubs de motards. Elle est mariée à Jason Polodovich et a avec lui trois enfants malgré ses airs de jeune rebelle. Elle a également deux filles adoptives de 16 ans, des jumelles, Lana et Fina. Elle s’entraine à la boxe entre une et quatre heures, toutes les nuits."}]},{"id":"antisysteme-p38-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","???"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p39-waylon-hunt","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Waylon Hunt","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Hell Angels","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Waylon Hunt","identity_keys":["Waylon Hunt","Chapter “Cruel angels” : Waylon Hunt"],"statut":"présidence de Motorcycle Club","organisation":"Hell Angels","age":"48 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p39-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Waylon Hunt"],["Alias / désignation","Chapter “Cruel angels” : Waylon Hunt"],["Âge apparent","48 ans"],["Affiliations","crawlers : gundrivers"],["Nationalité d’origine","Américaine"],["Organisation","Hell Angels"],["Statut","présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p39-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ancien membre de l’US. Navy, chez les Navy seals, il n’a pas spécialement eu de distinctions pendant la guerre, bien qu’on sache peu de chose sur ses actions. Avant la guerre c’était un pomper de San Francisco. Au retour, il trouva sa ville dévastée, un immense cratère en son cœur, des crevasses encore ouvertes un peu partout, sa famille avait eu le bon gout d’être identifiable dans les victimes, mais enterrer deux gamins de 12 et 14 ans, une femme, deux sœurs, leurs enfants, leurs conjoints, ses parents et ses collègues restés, tout cela pesa un peu trop sur un homme simple comme Waylon. Trouvant une moto inutilisée, il la vola, sans précipitation et quitta, à jamais San Francisco. Taciturne et posé, c’est loin d’être le genre de gars au sang chaud, il a enduré chaque épreuve, chaque mission pour avoir son cuir, son statut de membre et finir président des « Cruel Angels », dont il ignore d’ailleurs que le fondateur était un fan d’animation japonaise. C’était un ami proche de « Jackal » et un ami de « Beaver », parti en Alaska, il était assez épris de la femme de ce dernier, la nord- coréenne traitresse, Ju-Han qu’il a aidé à venir en Californie très récemment."}]},{"id":"antisysteme-p39-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p39-angelino-molina","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Angelino Molina","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Hell Angels","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Angelino Molina","identity_keys":["Angelino Molina","Chapter “Hellsing Angels” : Angelino Molina"],"statut":"Motards","organisation":"Hell Angels","age":"","nationalite":"Argentin"},"sections":[{"id":"antisysteme-p39-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Angelino Molina"],["Alias / désignation","Chapter “Hellsing Angels” : Angelino Molina"],["Affiliations","crawler : gundriver"],["Nationalité d’origine","Argentin"],["Organisation","Hell Angels"]]}]},{"id":"antisysteme-p39-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Angelino Molina est un biker assez craint, éternellement en colère ou renfrogné, il ne se laisse presque jamais commander. Contrebandier assez efficace, il aide surtout les crawlers plus que les mafieux, cependant, il lui arrive de trucider ses clients s’il découvre la moindre trace de trahison."}]},{"id":"antisysteme-p39-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Apollyon -"],["Nature réelle","daemons"],["Âge réel / complément","30 ans », ????"],["Statut","présidence de Motorcycle Club"],["Divinité","Mammon"]]},{"type":"p","text":"Apollyon est le duc infernal de la destruction, il sert Mammon et est un des principaux alliés de l’archange Azrael dans ses missions, plus fiable qu’Erianel (Elisenda du garage Ashford) ou l’archange déchue Sachiel (mère Sasha Novogvna), il amène tout materiel nécessaire à la chasseuse que l’Association ne peut fournir. Ami des chasseurs, il veille sur la cartomancienne tant qu’il peut, et pour cause, il partage une certaine haine des vampires qu’il pense qu’elle possède puisque dans sa vie mortelle, il a été torturé et mutilé par Gahanath en personne avant d’être tué par son propre frère, Dragoy, quand il refusa à sacrifier les cavaliers à un sombre rituel. Mammon sauva son âme de la corruption, heureusement n’étant pas devenu vampire avant de mourir. C’est le plus grand ennemi Daemon des vampires et ce n’est pas pour rien qu’il aide sa nièce donc dès qu’elle en affronte."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p40-calvin-barron","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Calvin BARRON","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Cruisers","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Calvin BARRON","identity_keys":["Calvin BARRON","The Overspeed Baron: Calvin Barron"],"statut":"Chef de Motorcycle Club","organisation":"Cruisers","age":"47 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p40-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Calvin BARRON"],["Alias / désignation","The Overspeed Baron: Calvin Barron"],["Âge apparent","47 ans"],["Affiliations","crawlers Gundrivers"],["Nationalité d’origine","américaine"],["Organisation","Cruisers"],["Statut","Chef de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p40-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Calvin Barron n’a aucun dossier avant 2015, apparu du néant à 27 ans, il s’installa à l tête d’une petite bande de motard trafiquants et a été appelé sous les drapeaux en 2023, dans l’US. Navy. Il était sur presque tous les navires de Farah Al’Arshad. Après la guerre, il en est revenu aux motards, et a prodigieusement mené la suite du combat de Stephany Lorn, présidente des Cruisers et en guerre contre les Bandidos. C’est un homme très pragmatique et logique, là où on connait et reconnait son rival, Arthur Bartram, pour être une bête de combat, Calvin st bien plus intellectuel et la fore des cruisers c’est leur logistique prodigieuse, c’est comme ça qu’un club mineur a fait face aux bandidos, Hell Angels ou bien aux outlaws et leur a survécu là où seuls les Angels sont restés. Le fait qu’il ne dresse la Silver ne semble pas avoir joué plus que ça, pas plus qu’il ne soit marié avec Katerinochkina Angelika Ruslanovna, bien qu’on suppose que ce soit un mariage blanc, un service rendu aux russes en la naturalisant."}]},{"id":"antisysteme-p40-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"p","text":"Jusqu’en 2015, Calvin était un chevalier des Saintes Lagunes. Officiant en Russie essentiellement, c’était un chasseur de sorcières psycolor. Il a été trucidé par Stephania Volkov, sa partenaire, et laissé pour mort alors qu’il voulait dissimuler l’évasion d’une sorcière. Il se cache de l’ordre et de tous ceux religieux depuis, ignorant qu’au fond, tout le monde s’en fout coté Eglise comme des Saintes Lagunes."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p40-stephany-lorn","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Stephany Lorn","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Cruisers","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Stephany Lorn","identity_keys":["Stephany Lorn","Chapter “original Cruisers” : Stephany Lorn"],"statut":"vice-présidence de Motorcycle Club","organisation":"Cruisers","age":"42 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p40-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Stephany Lorn"],["Alias / désignation","Chapter “original Cruisers” : Stephany Lorn"],["Âge apparent","42 ans"],["Affiliations","crawlers : gundrivers"],["Nationalité d’origine","Américaine"],["Organisation","Cruisers"],["Statut","vice-présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p40-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Pendant la guerre, elle a été la présidente des Cruisers, le chapitre d’origine. C’est elle qui a réformé et réorganisé les motards de ce gang, évitant les confrontations, multipliant les actions et diversifiant les connexions. Ironiquement, elle perdit l’usage de ses jambes après un accident de moto en 2024, forcée de laisser la présidence à Tobias Palmer, mais ce dernier l’a toujours écoutée et n’était qu’un porte￾parole. On ne devient pas présidente d’un gang de motards blancs, encore moins un gang d’importance quand on est d’une mère mexicaine et d’un père sino-américain si on n’a pas quelque chose de plus à apporter, l’immense intelligence de Stephany était son atout. Quand Calvin Barron revint de la guerre, il ajouta deux éléments : des vétérans pour la force de frappe et son sens surhumain de l’organisation et de la planification, à eux deux, le gang écrasa les rivaux avec bien plus d’aisance que les Angels ne le faisaient et surtout beaucoup moins de balles et de sang."}]},{"id":"antisysteme-p40-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","???"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p41-lana-jackson","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Lana Jackson","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Cruisers","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Lana Jackson","identity_keys":["Lana Jackson","Chapter “Ironclad Warriors” : Lana Jackson"],"statut":"présidence de Motorcycle Club","organisation":"Cruisers","age":"28 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p41-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Lana Jackson"],["Alias / désignation","Chapter “Ironclad Warriors” : Lana Jackson"],["Âge apparent","28 ans"],["Affiliations","crawlers : gundrivers"],["Nationalité d’origine","Américaine"],["Organisation","Cruisers"],["Statut","présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p41-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Lana était une métisse du Bronx e New-York. Son père s’est engagé en 2023, son frère en 2025 et elle en 2027, à 19 ans. De toute sa famille elle est la seule à être revenue en vie. Sans plus d’attaches hormis sa mère, elle décida de joindre le Mexique pour faire mercenaire, mais en Californie en attendant de quitter le pays, elle renonça, rencontrant Saraya, une pute de biker dans un bar des cruisers. Folle de cette dernière, Lana mit tout en œuvre pour la séduire, à commencer par faire semblant d’être motarde. C’est en draguant qu’elle retrouva une passion et qu’elle fut séduite par la vie du Cruisers MC. Saraya fut tuée dans un échange avec les Bandidos, sa mort marqua une décision grave chez Lana : jamais elle ne quitterait les Cruisers avant d’avoir fait bouffer ses couilles à Djoreno Alvarez. En 2035, elle y parvint, attrapant sa Némésis après des années, elle le fit émasculer par sa femme, lui fit bouffer ses couilles et pendant qu’il mâchait, tua la femme avant de partir."}]},{"id":"antisysteme-p41-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p41-xander-lucas","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Xander Lucas","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Cruisers","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Xander Lucas","identity_keys":["Xander Lucas","Chapter “Armored fists”: Xander Lucas"],"statut":"présidence de Motorcycle Club","organisation":"Cruisers","age":"","nationalite":"americaine"},"sections":[{"id":"antisysteme-p41-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Xander Lucas"],["Alias / désignation","Chapter “Armored fists”: Xander Lucas"],["Affiliations","crawler : gundriver"],["Nationalité d’origine","americaine"],["Organisation","Cruisers"],["Statut","présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p41-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Xander Lucas est un président de chapitre des Cruisers, les « Armored Fists ». C’est un criminel recherché et une brute notoire. Il a pour lui d’être assez fort et surtout assez résistant, on l’a déjà vu résister à des rafales de tirs par son seul gabarit colossal. Il n’est ni très malin ni très discret, en revanche, c’est un exécutant très méticuleux. On pourrait douter qu’un tel caractère ne soit adapté à la tête d’un chapitre, mais les « Armored fists » sont éternellement associés au bar « Dreadnought » où tous les « Cruisers » se rassemblent. Ils en sont les gardes et les sentinelles, de fait c’est un chapitre qui a assez peu de missions complexes ou qui ne nécessite de gérer des situations seul. En revanche c’est un chapitre dont on attend un engagement total et Xander est le parfait président pour accomplir cela. Il est Biogmenté, il a été incorporé au programme de Biosun (Melvin Brock,Josh Graff etc.) après son arrestation en 2034 et a été libéré en janvier 2035, il est revenu avec 95 kilo de muscles en plus, un meilleur contrôle sur ses pensées, 40 cm de plus et une densité osseuse augmentée."}]},{"id":"antisysteme-p41-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","40 ans », ????"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p42-luther-pierce","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Luther PIERCE","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Reapers Incorporated Power","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Luther PIERCE","identity_keys":["Luther PIERCE","The Reaper boss: Luther Pierce"],"statut":"Chef de Motorcycle Club","organisation":"Reapers Incorporated Power","age":"32 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p42-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Luther PIERCE"],["Alias / désignation","The Reaper boss: Luther Pierce"],["Âge apparent","32 ans"],["Affiliations","crawlers Gundrivers"],["Nationalité d’origine","américaine"],["Organisation","Reapers Incorporated Power"],["Statut","Chef de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p42-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Les « grim reapers » ont été fondé dans les années 2010, à Los Angeles, un gang de quartier à l’origine. Non racialisé, ce gang mettait à l’épreuve ses membres par des étapes de plus en plus rudes. S’inspirant de mouvements punks et de la culture motarde, ils géraient les combats de rue, la distribution de la drogue et l’’extorsion auprès des deux bars du quartier. Fondé par Tobias Fockell, (père d’Addisson Fockell dit « Fox »), le gang est revenu aux mains de Solomon Blackburn, un psychopathe ayant renforcé le délire autour de la Faucheuse, c’est sous sa direction que le gang ouvrit ses horizons et prit des femmes comme membres, dont la jeune Veronica Silver qui sortait avec Keith Hayes. C’est Veronica qui recruta elle-même un jeune afro-américain, Luther Pierce avant qu’il ne joigne les Crips, un grand gang. Malin, vicieux et très athlétique, il était le seul à pouvoir suivre son mentor, Vero. Quand elle tua Ted Merrill, Kayleigh Zamora, la nouvelle chef des Reapers en fut soulagée, voyant Veronica comme une rivale dans un avenir proche, elle essaya de la balancer à la police et de virer Luther. Veronica s’engagea dans l’armée mais pour Luther, ce fut un passage à vide, après un temps chez les Cruisers, il revint en 2022 reprendre le gang, aidé par Daldea FANN, une militaire ayant un compte à régler avec Kayleigh. Réformant le RIP, il en fin un gang de bikers diversifié. Il combattit 2 ans en Corée avant de reprendre ses affaires de gangs après 2025."}]},{"id":"antisysteme-p42-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p42-daldea-fann","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Daldea FANN","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Reapers Incorporated Power","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Daldea FANN","identity_keys":["Daldea FANN","Chapter “Grim reapers” : Daldéa Fann"],"statut":"Motards","organisation":"Reapers Incorporated Power","age":"45 ans  - ?? ans","nationalite":"suisse"},"sections":[{"id":"antisysteme-p42-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Daldea FANN"],["Alias / désignation","Chapter “Grim reapers” : Daldéa Fann"],["Âge apparent","45 ans  - ?? ans"],["Affiliations","chasseurs – crawlers : Gundrivers"],["Nationalité d’origine","suisse"],["Organisation","Reapers Incorporated Power"]]}]},{"id":"antisysteme-p42-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Pilote d’hélicoptère de combat et pilote d’essai pendant la guerre, elle a été collègue de Makana Keahi et Abigael Sky. Après un temps comme mercenaire sous les Ordres d’Andrea Shield, elle a fini par devenir biker. Elle passe de club en club sans trop d’attachement, actuellement, elle est Reapers."}]},{"id":"antisysteme-p42-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Daldea FANN"],["Nature réelle","Elfe"],["Statut","vice-présidence de Motorcycle Club"]]},{"type":"p","text":"C’est une ancienne elfe noire née sur Aèr, elle y aurait été assez criminelle, elle appartient à la Chasse fantastique, Titania étant une des rares capables de lui tenir tête au combat, même si sa maitrise de lance est réputée. Amie d’Arianwen, la chasseuse religieuse ou bien de Kain, le démon, elle est peu attachée aux gens, possiblement lassée de sa trop longue vie. Elle n’a ni pudeur ni grand sens de l’honneur, elle est capable de mentir allégrement sans honte malgré une facette très guerrière. Ancienne chevaucheuse de Wyverne, elle a un gout prononcé pour les véhicules volants. Elle mentait souvent en se présentant comme un Chevalier dragon d’Irieth, mais peu d’exilés comprennent ce que ça signifie désormais, alors elle ne le dit que rarement. Elle a un caractère absolument impossible, invivable quand elle se donne la peine de parler, taciturne au possible avec ceux qui n’ont rien pour la motiver."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p43-addison-fockell-fox","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Addison Fockell –  fox","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Reapers Incorporated Power","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Addison Fockell –  fox","identity_keys":["Addison Fockell –  fox","Addison Fockell – « fox »","Chapter “Blood reapers” : Addison Fockell"],"statut":"présidence de Motorcycle Club","organisation":"Reapers Incorporated Power","age":"35 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p43-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Addison Fockell –  fox"],["Alias / désignation","Chapter “Blood reapers” : Addison Fockell"],["Âge apparent","35 ans"],["Affiliations","crawlers : gundrivers"],["Nationalité d’origine","Américaine"],["Organisation","Reapers Incorporated Power"],["Statut","présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p43-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Addison Fockell est a fille unique du fondateur, Tobias Fockell, qui créa le gang en 2010, il fut vite arrêté sans balancer son gang et Solomon Blackburn prit la suite en 2014, Addison n’avait que 14 ans alors elle ne s’approcha pas des Reapers, bien que Solomon fût un « oncle » pour elle."}]},{"id":"antisysteme-p43-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"p","text":"Ce dernier quitta le gang pour des raisons personnelle (passant chasseur), Addison perdant sa mère assez tôt, en 2017, elle passa en foyer le temps que la procédure d’émancipation ne soit actée, elle fit serveuse dans le bar des Reapers le temps de pouvoir s’engager, une reapers, Veronica Silver ayant récemment intégré l’armée Addisson, sans la connaitre plus que ça s’en inspira avec quelques années de retard. Elle se montra efficace et se retrouva dans le bataillon des « Animals » de Bartram, dans l’US. Army. Après la guerre, elle fit mercenaire en 2028 avant de revenir à ses racines en joignant Pierce chez les Reapers, surprise d voir que le petit gang était devenu un club très organisé de contrebandiers."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p43-solomon-blackburn","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Solomon Blackburn","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Reapers Incorporated Power","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Solomon Blackburn","identity_keys":["Solomon Blackburn","Chapter “Lost reapers”: Solomon Blackburn"],"statut":"présidence de Motorcycle Club","organisation":"Reapers Incorporated Power","age":"","nationalite":"sud-africaine > américaine"},"sections":[{"id":"antisysteme-p43-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Solomon Blackburn"],["Alias / désignation","Chapter “Lost reapers”: Solomon Blackburn"],["Affiliations","crawler : gundriver – chasseur - AIDH"],["Nationalité d’origine","sud-africaine > américaine"],["Organisation","Reapers Incorporated Power"],["Statut","présidence de Motorcycle Club"],["Nature","humaine (homo superior)"]]}]},{"id":"antisysteme-p43-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Solomon Blackburn a été le second chef du gang des Reapers, il est connu pour avoir accepté les femmes et les afro-américains pour ne pas transformer le gang en le rapprochant de néonazis et il est aussi connu pour avoir quitté le gang du jour au lendemain pour traquer un type et le tuer dans le désert, sans revenir avant des années. Il a fondé le « Reaper skulls», où Tanako Akaguchi, Rena Queen et d’autres assassines sont des membres (white skull, black skulls, red skull, blue skull etc.) et le « Lost reapers », un chapitre de motards, un gang frère des « grim reapers » avec lequel ils créèrent le « RIP » en rattachant plusieurs gangs entre eux, dans une organisation bien ficelée."}]},{"id":"antisysteme-p43-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","45 ans », ????"]]},{"type":"p","text":"Sergent de l’AIDH, Blackburn est en mission spéciale, il traque la « Black Star », pour cela il a intégré l’Association de chasseurs et est membre du Hunt100, il a été déçu de ne pas pouvoir être la « faucheuse », la meilleure chasseuse du hunt15 ayant déjà le pseudonyme. Il entraine les « Reaper skulls » selon des méthodes de l’AIDH, bien qu’elles ne chassent pas dans la Vérité, elles sont un soutien qu’il utilise quand il a besoin d’aide sans qu’il n’en réfère à ses supérieurs. Ironiquement les « reaper skulls » attaquèrent Veronica Silver, une petite qu’il avait intégré aux Grim reapers et dont le talent lui a directement inspiré la création des Reapers skulls après la guerre sans qu’aucune ne sache le lien."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p44-miguel-gonzalez","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Miguel Gonzalez","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Vagos","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Miguel Gonzalez","identity_keys":["Miguel Gonzalez","Miguel Gonzalez / Carl Thomson","Loki’son: Miguel González","Carl Thomson"],"statut":"Chef de Motorcycle Club","organisation":"Vagos","age":"52 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p44-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Miguel Gonzalez"],["Alias / désignation","Loki’son: Miguel González"],["Âge apparent","52 ans"],["Affiliations","crawlers Gundrivers"],["Nationalité d’origine","américaine"],["Organisation","Vagos"],["Statut","Chef de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p44-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Les « Vagos » ont été fondé dans les années 1963, à San Bernardino."}]},{"id":"antisysteme-p44-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"p","text":"Leur logo est Loki, le dieu nordique et « Vagos » signifie « vagabond ». Ce n’est pas un groupe hispanique à l’origine, dans leur histoire, les Vagos ont toujours été un groupe proche si ce n’était Neonazi. C’est durant les années 2030 que l’orientation changea, Cruisers et hell Angels, des ennemis prenant l’intégralité des commerce avec les irlandais, les russes et les américains d’autres états, les vagos, face à la disparition des bandidos, eux aussi moins hispaniques que leur nom ne le suggère, que le Vagos MC s’est rapproché des cartels mexicains, initialement leur guerre de gangs avec les motards mexicains était territorial mais s’est vite mué en une guerre pour servir les cartels, essentiellement de Tijuana puis du Sinaloa. les Vagos ont assimilé les gangs vaincus, forçant peu à peu leurs anciennes lignes de conduites et idéologies racistes à sauter. Carl Thomson, un ancien du NROA (new reich of America) préféra échapper à la police en devenant Miguel Gonzalez, le président du principal chapitre. Violent et haineux, il a une dent contre Todd Larsen, qui l’ a vendu au LAUS pour protéger son propre cul."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p44-adalyn-owens-peacock","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Adalyn Owens –  peacock","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Vagos","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Adalyn Owens –  peacock","identity_keys":["Adalyn Owens –  peacock","Adalyn Owens – « peacock »","Chapter “Los pícaros” : Adalyn Owens"],"statut":"Motards","organisation":"Vagos","age":"55 ans  - ?? ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p44-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Adalyn Owens –  peacock"],["Alias / désignation","Chapter “Los pícaros” : Adalyn Owens"],["Âge apparent","55 ans  - ?? ans"],["Affiliations","crawlers : Gundrivers/necropunks"],["Nationalité d’origine","américaine"],["Organisation","Vagos"]]}]},{"id":"antisysteme-p44-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Adalyn est une femme qui a incorporé les vagos assez jeune, pas une pute à motard ni même une régulière, même pas une fille de motard, elle est venue, a brisé des testicules, descendu des bières, essuyé des tirs, sauvé des gars et a obtenu son cuir en partant de plus loin qu’aucun autre Vagos. 35 ans plus tard, les « Fourbes » (los Picaros), sont le chapitre des vagos qu’elle dirige, des malades mentaux de pillards, des necropunks, ils se baladent avec les os des gens qu’ils ont tués, les attachant à leur moto. Elle a fait la guerre, elle était chez les rangers, elle était des « Animals », sous le commandement de « bears », alias « Odin », et plus raisonnablement appelé Arthur Bartram. Elle ne s’est jamais entendue avec lui, elle était Vagos, lui hell Angels, et même avec la guerre, l’esprit de corps des soldats, rien n’y faisait. En revanche, elle s’est, le temps d’une opération, assez bien entendu avec Tokala."}]},{"id":"antisysteme-p44-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Aelyniel"],["Nature réelle","angelus"],["Statut","présidence de Motorcycle Club"]]},{"type":"p","text":"Angelus de Gabrielle, elle est une artisane de la discorde, adorant foutre la merde et jeter des petites pistes de désaccords entre les gens les plus amis ou les plus liés entre eux. Ses pouvoirs n’ont jamais marché sur Bartram, sa volonté étant immense et elle ne l’a jamais accepté."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
